#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include "kernel.h"
#include <cmath>
#include <string>

static void check_bf16_contiguous_cuda(
    const torch::Tensor& tensor, const std::string& name) {
    TORCH_CHECK(tensor.is_cuda(), name, " must be a CUDA tensor");
    TORCH_CHECK(
        tensor.dtype() == torch::kBFloat16,
        name, " must have bfloat16 dtype, got ", tensor.dtype());
    TORCH_CHECK(tensor.is_contiguous(), name, " must be contiguous");
}

// Destination-passing-style entry. Per definition.json:
//   grad_output         : [batch_size, seq_len, hidden_size=4096] bf16
//   gate                : scalar bf16 (zero-dim tensor)
//   hidden_states       : [batch_size, seq_len, hidden_size=4096] bf16
//   mask                : [batch_size, seq_len, 1] bf16
//   grad_residual       : [batch_size, seq_len, hidden_size]      bf16 (DPS)
//   grad_hidden_states  : [batch_size, seq_len, hidden_size]      bf16 (DPS)
//   grad_gate           : scalar bf16                              (DPS)
//
// hidden_size = 4096 is pinned; batch_size and seq_len are
// workload-variable.
void run(
    const torch::Tensor& grad_output,
    const torch::Tensor& gate,
    const torch::Tensor& hidden_states,
    const torch::Tensor& mask,
    torch::Tensor grad_residual,
    torch::Tensor grad_hidden_states,
    torch::Tensor grad_gate
) {
    TORCH_CHECK(grad_output.dim() == 3,
                "grad_output must be 3D [B, S, H]");
    TORCH_CHECK(hidden_states.dim() == 3,
                "hidden_states must be 3D [B, S, H]");
    TORCH_CHECK(mask.dim() == 3,
                "mask must be 3D [B, S, 1]");
    TORCH_CHECK(grad_residual.dim() == 3,
                "grad_residual must be 3D");
    TORCH_CHECK(grad_hidden_states.dim() == 3,
                "grad_hidden_states must be 3D");
    TORCH_CHECK(gate.dim() == 0,
                "gate must be a zero-dim scalar tensor, got dim=",
                gate.dim());
    TORCH_CHECK(grad_gate.dim() == 0,
                "grad_gate must be a zero-dim scalar tensor, got dim=",
                grad_gate.dim());

    constexpr int64_t kHiddenSize = 4096;
    TORCH_CHECK(grad_output.size(2) == kHiddenSize,
                "hidden_size must be ", kHiddenSize,
                " for problem_061, got ", grad_output.size(2));
    TORCH_CHECK(hidden_states.sizes() == grad_output.sizes(),
                "hidden_states shape must match grad_output");
    TORCH_CHECK(mask.size(0) == grad_output.size(0) &&
                mask.size(1) == grad_output.size(1) &&
                mask.size(2) == 1,
                "mask must have shape [B, S, 1] matching grad_output");
    TORCH_CHECK(grad_residual.sizes() == grad_output.sizes(),
                "grad_residual shape must match grad_output");
    TORCH_CHECK(grad_hidden_states.sizes() == grad_output.sizes(),
                "grad_hidden_states shape must match grad_output");

    check_bf16_contiguous_cuda(grad_output, "grad_output");
    check_bf16_contiguous_cuda(gate, "gate");
    check_bf16_contiguous_cuda(hidden_states, "hidden_states");
    check_bf16_contiguous_cuda(mask, "mask");
    check_bf16_contiguous_cuda(grad_residual, "grad_residual");
    check_bf16_contiguous_cuda(grad_hidden_states, "grad_hidden_states");
    check_bf16_contiguous_cuda(grad_gate, "grad_gate");

    // Host-side scalar evaluation of tanh(gate) and sech²(gate).
    // Gate is a zero-dim BF16 tensor; read its single element to
    // the host as fp32, evaluate the two constants once per
    // kernel invocation, and pass them as float kernel arguments.
    // `item<float>()` performs the scalar device-to-host read directly.  The
    // previous `gate.to(kFloat32).item<float>()` materialized a one-element
    // ATen CUDA conversion kernel inside the profiler gate, which made the
    // native vertical depend on a libtorch control sidecar for no semantic
    // benefit.
    const float gate_f32 = gate.item<float>();
    const float tanh_g = std::tanh(gate_f32);
    const float sech2 = 1.0f - tanh_g * tanh_g;

    // Per-row partial-sum buffer for the grad_gate reduction.
    const int64_t num_rows = grad_output.size(0) * grad_output.size(1);
    auto row_partials = at::empty(
        {num_rows}, grad_output.options().dtype(torch::kFloat32));

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();

    // Kernel A: per-row grad_hidden_states + row partial sums.
    problem_061_grad_hidden_launcher(
        grad_output, hidden_states, mask,
        tanh_g, grad_residual, grad_hidden_states, row_partials, stream);

    // Kernel B: single-CTA reduction of row_partials -> grad_gate.
    problem_061_grad_gate_reduce_launcher(
        row_partials, sech2, grad_gate, stream);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def(
        "run", &run,
        "BF16 tanh-gated residual-addition backward: identity copy "
        "for grad_residual, per-element transform for "
        "grad_hidden_states, two-pass reduction for the scalar "
        "grad_gate. hidden_size=4096 pinned.");
}

#include "kernel.h"
#include <cuda_bf16.h>
#include <cuda_runtime.h>

// BF16 tanh-gated residual-addition backward.
//
// Kernel A: per-(b, s) row CTA over the pinned hidden_size = 4096
// BF16 elements. Each thread (1) writes grad_hidden_states[b, s, h]
// = bf16(grad_output[b, s, h].f32 * tanh_g * mask[b, s, 0].f32) and
// (2) accumulates partial_sum += grad_output[b, s, h] *
// hidden_states[b, s, h] * mask[b, s, 0] in fp32. Warp-shuffle +
// 8-way cross-warp tree reduces partial_sum to a single fp32 per
// CTA; thread 0 writes row_partials[b*S + s].
//
// Kernel B: single-CTA reduction of the row_partials[N=B*S] fp32
// buffer. BLOCK_THREADS = 256. Each thread stride-loops over the
// buffer, accumulating into a fp32 register; warp-shuffle + 8-way
// cross-warp tree reduces; thread 0 multiplies by sech² and writes
// bf16(total_sum * sech2) to the zero-dim grad_gate output.

namespace {

constexpr int kHiddenSize = 4096;
constexpr int kHiddenPairs = kHiddenSize / 2;  // BF16x2 view
constexpr int kBlockThreads = 256;
constexpr int kWarpSize = 32;
constexpr int kNumWarps = kBlockThreads / kWarpSize;  // 8

__device__ inline float warp_reduce_sum(float v) {
    #pragma unroll
    for (int off = kWarpSize / 2; off > 0; off >>= 1) {
        v += __shfl_xor_sync(0xffffffff, v, off);
    }
    return v;
}

__global__ void __launch_bounds__(kBlockThreads, 4)
problem_061_grad_hidden_kernel(
    const __nv_bfloat16* __restrict__ grad_output,
    const __nv_bfloat16* __restrict__ hidden_states,
    const __nv_bfloat16* __restrict__ mask,
    __nv_bfloat16* __restrict__ grad_residual,
    __nv_bfloat16* __restrict__ grad_hidden_states,
    float* __restrict__ row_partials,
    float tanh_g) {

    const int row = blockIdx.x;          // row = b * S + s
    const int tid = threadIdx.x;
    const int row_offset = row * kHiddenSize;
    const __nv_bfloat16 mask_b16 = mask[row];      // mask[b, s, 0]
    const float mask_val = __bfloat162float(mask_b16);
    // Broadcast pair for the bf16-multiply-then-cast contract.
    const __nv_bfloat162 mask_pair_b16 =
        __bfloat162bfloat162(mask_b16);

    const __nv_bfloat162* go_row_vec =
        reinterpret_cast<const __nv_bfloat162*>(grad_output + row_offset);
    const __nv_bfloat162* hs_row_vec =
        reinterpret_cast<const __nv_bfloat162*>(hidden_states + row_offset);
    __nv_bfloat162* ghs_row_vec =
        reinterpret_cast<__nv_bfloat162*>(grad_hidden_states + row_offset);

    float partial_sum = 0.0f;
    const float gate_mask = tanh_g * mask_val;

    for (int i = tid; i < kHiddenPairs; i += kBlockThreads) {
        const __nv_bfloat162 g_pair = __ldg(go_row_vec + i);
        const __nv_bfloat162 h_pair = __ldg(hs_row_vec + i);
        const float2 g_f2 = __bfloat1622float2(g_pair);

        // grad_hidden_states = grad_output * tanh_g * mask  (fp32 math,
        // matching the reference's fp32 cast chain `grad_output * tanh_g *
        // mask` before the final bf16 store).
        const float y0 = g_f2.x * gate_mask;
        const float y1 = g_f2.y * gate_mask;
        reinterpret_cast<__nv_bfloat162*>(grad_residual + row_offset)[i] = g_pair;
        ghs_row_vec[i] = __float22bfloat162_rn(make_float2(y0, y1));

        // Accumulator for grad_gate:
        //   sum(grad_output.f32 * (hidden_states * mask).bf16.f32)
        // The reference computes `masked_hidden_states = hidden_states *
        // mask` in BF16 BEFORE casting to fp32 (both factors are BF16, so
        // PyTorch's default dispatch runs the multiply in BF16 with BF16
        // rounding). To match the reference's numerics exactly, multiply
        // `h_pair * mask_pair_b16` in BF16 via `__hmul2` first, then
        // cast the product to fp32 and accumulate.
        const __nv_bfloat162 hm_pair = __hmul2(h_pair, mask_pair_b16);
        const float2 hm_f2 = __bfloat1622float2(hm_pair);
        partial_sum += g_f2.x * hm_f2.x + g_f2.y * hm_f2.y;
    }

    // Warp + cross-warp reduction.
    partial_sum = warp_reduce_sum(partial_sum);
    __shared__ float warp_sums[kNumWarps];
    const int warp_id = tid / kWarpSize;
    const int lane_id = tid % kWarpSize;
    if (lane_id == 0) {
        warp_sums[warp_id] = partial_sum;
    }
    __syncthreads();

    if (tid == 0) {
        float total = 0.0f;
        #pragma unroll
        for (int w = 0; w < kNumWarps; ++w) {
            total += warp_sums[w];
        }
        row_partials[row] = total;
    }
}

__global__ void __launch_bounds__(kBlockThreads, 1)
problem_061_grad_gate_reduce_kernel(
    const float* __restrict__ row_partials,
    __nv_bfloat16* __restrict__ grad_gate,
    int num_rows,
    float sech2) {

    const int tid = threadIdx.x;

    float partial = 0.0f;
    for (int i = tid; i < num_rows; i += kBlockThreads) {
        partial += row_partials[i];
    }

    partial = warp_reduce_sum(partial);
    __shared__ float warp_sums[kNumWarps];
    const int warp_id = tid / kWarpSize;
    const int lane_id = tid % kWarpSize;
    if (lane_id == 0) {
        warp_sums[warp_id] = partial;
    }
    __syncthreads();

    if (tid == 0) {
        float total = 0.0f;
        #pragma unroll
        for (int w = 0; w < kNumWarps; ++w) {
            total += warp_sums[w];
        }
        const float result = sech2 * total;
        grad_gate[0] = __float2bfloat16_rn(result);
    }
}

}  // namespace

void problem_061_grad_hidden_launcher(
    const torch::Tensor& grad_output,
    const torch::Tensor& hidden_states,
    const torch::Tensor& mask,
    float tanh_g,
    torch::Tensor& grad_residual,
    torch::Tensor& grad_hidden_states,
    torch::Tensor& row_partials,
    cudaStream_t stream) {

    const int64_t batch_size = grad_output.size(0);
    const int64_t seq_len = grad_output.size(1);
    const int num_rows = static_cast<int>(batch_size * seq_len);

    dim3 grid(num_rows);
    dim3 block(kBlockThreads);

    problem_061_grad_hidden_kernel<<<grid, block, 0, stream>>>(
        reinterpret_cast<const __nv_bfloat16*>(
            grad_output.data_ptr<at::BFloat16>()),
        reinterpret_cast<const __nv_bfloat16*>(
            hidden_states.data_ptr<at::BFloat16>()),
        reinterpret_cast<const __nv_bfloat16*>(
            mask.data_ptr<at::BFloat16>()),
        reinterpret_cast<__nv_bfloat16*>(
            grad_residual.data_ptr<at::BFloat16>()),
        reinterpret_cast<__nv_bfloat16*>(
            grad_hidden_states.data_ptr<at::BFloat16>()),
        row_partials.data_ptr<float>(),
        tanh_g);
}

void problem_061_grad_gate_reduce_launcher(
    const torch::Tensor& row_partials,
    float sech2,
    torch::Tensor& grad_gate,
    cudaStream_t stream) {

    const int num_rows = static_cast<int>(row_partials.numel());

    dim3 grid(1);
    dim3 block(kBlockThreads);

    problem_061_grad_gate_reduce_kernel<<<grid, block, 0, stream>>>(
        row_partials.data_ptr<float>(),
        reinterpret_cast<__nv_bfloat16*>(
            grad_gate.data_ptr<at::BFloat16>()),
        num_rows,
        sech2);
}

#pragma once

#ifndef PROBLEM_061_TANH_GATED_RESIDUAL_ADD_BACKWARD_KERNEL_H
#define PROBLEM_061_TANH_GATED_RESIDUAL_ADD_BACKWARD_KERNEL_H

#include <cuda_runtime.h>
#include <torch/extension.h>

// Host launcher set for the BF16 tanh-gated residual-addition
// backward kernels. The reference forward is:
//   output = residual + tanh(gate) * hidden_states * mask
// with mask broadcast over the final hidden_size axis. The
// backward gradients are:
//   grad_residual       = grad_output                    # identity
//   grad_hidden_states  = grad_output * tanh(gate) * mask  # per-element
//   grad_gate           = sech²(gate) *
//                         Σ_{b,s,h} grad_output * hidden_states * mask
//
// The gate is a zero-dim BF16 scalar input, so `tanh_g` and
// `sech²(g) = 1 - tanh²(g)` are evaluated ONCE on the host and
// passed to the device kernels as `float` scalar arguments.
//
// Kernel A computes grad_hidden_states + per-(b, s) row partial
// sums of `(grad_output * hidden_states * mask)` into a
// `row_partials[B*S]` fp32 buffer. Kernel B does a single-CTA
// tree reduction of that buffer, scales by `sech²(gate)`, casts
// to BF16, and writes to the zero-dim grad_gate output tensor.
//
// hidden_size = 4096 is pinned; batch_size and seq_len are
// workload-variable. The grad_residual = grad_output identity
// copy is handled in main.cpp via `output.copy_(input)` rather
// than a dedicated kernel.
void problem_061_grad_hidden_launcher(
    const torch::Tensor& grad_output,
    const torch::Tensor& hidden_states,
    const torch::Tensor& mask,
    float tanh_g,
    torch::Tensor& grad_residual,
    torch::Tensor& grad_hidden_states,
    torch::Tensor& row_partials,
    cudaStream_t stream);

void problem_061_grad_gate_reduce_launcher(
    const torch::Tensor& row_partials,
    float sech2,
    torch::Tensor& grad_gate,
    cudaStream_t stream);

#endif  // PROBLEM_061_TANH_GATED_RESIDUAL_ADD_BACKWARD_KERNEL_H
